    // ...
};

Vector v1(7); // OK: v1은 7개 요소를 포함
Vector v2 = 7; // 에러: int에서 Vector로 암묵적인 변환 불가

Vector::Vector(const Vector& a) // 복사 생성자
    :elem{new double[a.sz]}, // 요소를 저장할 공간 할당
    sz{a.sz}
{
    for (int i=0; i!=sz; ++i) // 요소를 복사
        elem[i] = a.elem[i];
}

Vector& Vector::operator=(const Vector& a) // 복사 대입
{
    double* p = new double[a.sz];
    for (int i=0; i!=a.sz; ++i)
        p[i] = a.elem[i];
    delete[] elem; // 예전 요소 삭제
    elem = p;
    sz = a.sz;
    return *this;
}

Vector operator+(const Vector& a, const Vector& b)
{
    if (a.size()!=b.size())
        throw Vector_size_mismatch{};
    Vector res(a.size());

    for (int i=0; i!=a.size(); ++i)
        res[i]=a[i]+b[i];
    return res;
}

Vector::Vector(Vector&& a)
    :elem{a.elem}, // 인자로부터 요소를 가져옴
    sz{a.sz}
{
    a.elem = nullptr; // 이제 요소를 포함하지 않음
    a.sz = 0;
}

